export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball started this step so the (sweep) brick collision
  // can both catch fast jumps and find a face to bounce off (see #1).
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

