  const contacts = state.bricks.filter(
    (b) => b.alive && sweptOverlaps(x0, y0, ball.x, ball.y, ball.r, b),
  );
  if (!contacts.length) return false;

  for (const brick of contacts) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Tunnelled clean through: the ball no longer overlaps anything, so there is
  // no face or brick edge to push out of. Bounce the dominant travel axis.
  if (!contacts.some((b) => collides(ball, b))) {
    if (Math.abs(ball.vx) >= Math.abs(ball.vy)) ball.vx = -ball.vx;
    else ball.vy = -ball.vy;
    return true;
  }

  // Which border did the ball cross? For each brick compute how deep it sits in
  // on every side; the smallest depth across the group is the face to bounce.
  let hitBrick = null;
  let hitFace = null; // 'l' | 'r' | 't' | 'b' of the crossed border
  let minX = Infinity;
  let minY = Infinity;
  for (const brick of contacts) {
    const dL = ball.x + ball.r - brick.x; // ball entered through the LEFT border
    const dR = brick.x + brick.w - (ball.x - ball.r); // ...RIGHT border
    const dT = ball.y + ball.r - brick.y; // ...TOP border
    const dB = brick.y + brick.h - (ball.y - ball.r); // ...BOTTOM border
    if (dL > 0 && dL < minX) { minX = dL; hitBrick = brick; hitFace = 'l'; }
    if (dR > 0 && dR < minX) { minX = dR; hitBrick = brick; hitFace = 'r'; }
    if (dT > 0 && dT < minY) { minY = dT; hitBrick = brick; hitFace = 't'; }
    if (dB > 0 && dB < minY) { minY = dB; hitBrick = brick; hitFace = 'b'; }
  }
  if (!hitBrick) return true;

  const corner = Math.abs(minX - minY) <= 2; // diagonal hit
  if (corner) {
    // Diagonal: flip both components and push out of the entered corner.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x =
      ball.x < hitBrick.x + hitBrick.w / 2
        ? hitBrick.x - ball.r
        : hitBrick.x + hitBrick.w + ball.r;
    ball.y =
      ball.y < hitBrick.y + hitBrick.h / 2
        ? hitBrick.y - ball.r
        : hitBrick.y + hitBrick.h + ball.r;
    return true;
  }

  if (minX <= minY) {
    // Side hit: the ball grazed one of the two vertical borders (hitFace 'l'
    // = grazed the left border from outside-left, 'r' = the right border from
    // outside-right). Reflect vx and push it back to the grazing side; vy is
    // left exactly as it was.
    if (hitFace === 'l') {
      ball.x = hitBrick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = hitBrick.x + hitBrick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else {
    // Top/bottom hit: the ball grazed one of the two horizontal borders
    // (hitFace 't' = grazed the top border from above, 'b' = the bottom border
    // from below). Reflect vy and push it back to the grazing side; vx is left
    // exactly as it was.
    if (hitFace === 't') {
      ball.y = hitBrick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = hitBrick.y + hitBrick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
  return true;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
