    // = grazed the left border from outside-left, 'r' = the right border from
    // outside-right). Reflect vx and push it back to the grazing side; vy is
    // left exactly as it was.
    if (bestFace === 'l') {
      ball.x = hitBrick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = hitBrick.x + hitBrick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else {
    // Top/bottom hit: the ball grazed one of the two horizontal borders
    // (bestFace 't' = grazed the top border from above, 'b' = the bottom border
    // from below). Reflect vy and push it back to the grazing side; vx is left
    // exactly as it was.
    if (bestFace === 't') {
      ball.y = hitBrick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = hitBrick.y + hitBrick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
  return true;
}

